# owner: platform
"""Snap span edges to a fixed step for payroll."""

from typing import Iterable, List

from hourglass.parsing import format_span
from hourglass.models import Span


def check_step(step: int) -> None:
    """Step must be positive and divide an hour."""
    if step <= 0 or 60 % step != 0:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def snap_minutes(value: int, step: int) -> int:
    """Nearest multiple of step. Halfway rounds up."""
    return (value + step // 2) // step * step


def round_span(span: Span, step: int) -> Span:
    """Round both edges. Raises if the span collapses."""
    check_step(step)
    start = snap_minutes(span.start, step)
    end = snap_minutes(span.end, step)
    if start == end:
        raise ValueError(f"{span} vanishes at step {step}")
    return Span(start, end)


def span_label(span: Span) -> str:
    """Text such as 09:00-17:15 (8h 15m)."""
    hours, extra = divmod(span.minutes, 60)
    return f"{format_span(span)} ({hours}h {extra}m)"


def round_labels(
    spans: Iterable[Span], step: int
) -> List[str]:
    """One label per span, edges snapped to the step."""
    check_step(step)
    return [
        span_label(round_span(item, step))
        for item in spans
    ]

