# owner: platform
import unittest

from hourglass.rounding import (
    round_labels,
    round_span,
    snap_minutes
)
from hourglass.parsing import parse_span
from hourglass.models import Span


class SnapTests(unittest.TestCase):
    def test_rounds_to_nearest(self):
        self.assertEqual(snap_minutes(62, 15), 60)
        self.assertEqual(snap_minutes(68, 15), 75)

    def test_halfway_rounds_up(self):
        self.assertEqual(snap_minutes(15, 30), 30)


class RoundSpanTests(unittest.TestCase):
    def test_both_edges_move(self):
        result = round_span(parse_span("08:58-17:12"), 15)
        self.assertEqual(result, parse_span("09:00-17:15"))

    def test_edge_can_reach_midnight(self):
        result = round_span(parse_span("20:00-23:55"), 15)
        self.assertEqual(result.end, 24 * 60)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(61, 63), 15)


class LabelTests(unittest.TestCase):
    def test_label_format(self):
        span = parse_span("08:58-17:12")
        labels = round_labels([span], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span(self):
        spans = [parse_span("09:00-10:00"), Span(600, 665)]
        labels = round_labels(spans, 30)
        self.assertEqual(
            labels,
            ["09:00-10:00 (1h 0m)", "10:00-11:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])


class StepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        span = parse_span("09:00-10:00")
        for step in (0, -15, 7, 45, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([span], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps_work(self):
        span = parse_span("09:00-10:00")
        for step in (1, 5, 10, 15, 20, 30, 60):
            with self.subTest(step=step):
                labels = round_labels([span], step)
                self.assertEqual(len(labels), 1)
